-- Molten Core tier 1 (Classic sets 201-209, 72 pieces 16795-16868) had no ItemSparse row anywhere: the WoW Forever client
-- blanks them, and our server had none either, so every T1 piece in Molten Core loot was an invalid item and dropped
-- nothing (".additem 16802" said "Invalid item id"). The client still has their Item, appearance, set and set bonus rows.
-- Rows written from the Classic item data (Wowhead Classic): name, item level, quality, slot, classes, binding, sell price,
-- set, and each stat as its share of the item level's budget (RandPropPoints, the way the client and the server compute it);
-- armor comes out of the item level formula and matches Classic on all 72. Equip lines (spell damage, healing, mp5, hit,
-- crit) are item effects with the Classic spells. Everything is sent to clients through hotfix_data so tooltips show.
-- Live WoW Forever replaced these with its own copies (288823-288894, sets 2138-2146): item level 30, bind on equip,
-- level 1, half the Classic stats. We keep the Classic pieces at full stats on purpose, so the loot stays on 16795-16868.
-- Reported by Everlake (github.com/buildthehomelab/wow-everlake-world-data, GPL-3, #253); written fresh here.
DELETE FROM `item_sparse` WHERE `ID` IN (16795,16796,16797,16798,16799,16800,16801,16802,16803,16804,16805,16806,16807,16808,16809,16810,16811,16812,16813,16814,16815,16816,16817,16819,16820,16821,16822,16823,16824,16825,16826,16827,16828,16829,16830,16831,16833,16834,16835,16836,16837,16838,16839,16840,16841,16842,16843,16844,16845,16846,16847,16848,16849,16850,16851,16852,16853,16854,16855,16856,16857,16858,16859,16860,16861,16862,16863,16864,16865,16866,16867,16868);
-- item effects 9900313-9900412
DELETE FROM `item_effect` WHERE `ID` BETWEEN 9900313 AND 9900412;
DELETE FROM `item_x_item_effect` WHERE `ID` BETWEEN 9900313 AND 9900412;
-- hotfix_data 26112185-26112456
DELETE FROM `hotfix_data` WHERE `Id` BETWEEN 26112185 AND 26112456;
